// Build a hybrid_search() call so the 1536-dim vector and any
// comma/quote-bearing lexical text are passed safely (no positional queryReplacement).
const EXPECTED_DIMS = 1536;

// L2-normalize. gemini-embedding-001 only returns pre-normalized vectors
// at 3072 dims; at 1536 the API leaves them unnormalized.
function l2normalize(v) {
  let norm = 0;
  for (const x of v) norm += x * x;
  norm = Math.sqrt(norm);
  return norm > 0 ? v.map(x => x / norm) : v;
}

const trigger = $('When Executed by Another Workflow').first().json || {};
const lexical = String(trigger.lexical || trigger.query || '');
let filter = trigger.filter || '{}';
if (typeof filter !== 'string') filter = JSON.stringify(filter);
if (!filter.trim()) filter = '{}';

const embedding = $json.embedding && $json.embedding.values;
if (!Array.isArray(embedding)) {
  throw new Error('Embedding failed: ' + JSON.stringify($json).slice(0, 300));
}

// Fail here, at the source, rather than on the Postgres cast.
if (embedding.length !== EXPECTED_DIMS) {
  throw new Error('Query embedding is ' + embedding.length + ' dims, expected ' +
    EXPECTED_DIMS + ' - check outputDimensionality on the Embed Query node.');
}

const vector = '[' + l2normalize(embedding).join(',') + ']';

return [{ json: { lexical, vector, filter } }];

// Format retrieved chunks as a single text block with rich source labels,
// so the agent gets file + section context (which match_documents dropped).
const rows = $input.all();
const blocks = rows.map(item => {
  const j = item.json || {};
  const content = j.content;
  if (!content) return '';
  const meta = j.metadata || {};
  const source = meta.original_file_name || '';
  const section = meta.section_heading || '';
  const label = source && section ? source + ' \u2014 ' + section : (source || section || '');
  return label ? '[Source: ' + label + ']\n' + content : content;
}).filter(Boolean);

const response = blocks.length ? blocks.join('\n\n---\n\n') : 'No relevant documentation found.';
return [{ json: { response } }];
